def transform(grid):
    # Each cross marks a colored object's row and column. Extend each colored
    # marker's row/column across the canvas, preserving the crosses themselves.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 3) and r > 0 and r+1 < h and c > 0 and c+1 < w:
                if grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 3:
                    centers.append((r,c,grid[r][c]))
    for r,c,color in centers:
        for x in range(w):
            if out[r][x] == 0: out[r][x] = color
        for y in range(h):
            if out[y][c] == 0: out[y][c] = color
    return out
